"use client";

import { useEffect, useState, useMemo, useCallback } from "react";
import { createClient } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import { ErrorState } from "@/components/ui/error-state";
import { cn } from "@/lib/utils";
import {
  TrendingUp, Users, FileText,
  DollarSign, Target, Clock, AlertTriangle,
  ArrowUpRight, Activity, CheckCircle2, AlertCircle,
  BarChart3, PieChart, ShieldAlert, RotateCcw, GripHorizontal,
} from "lucide-react";
import { useLanguage } from "@/lib/i18n/LanguageContext";

/* ─── Types ─── */
interface Lead {
  id: string; customer_name: string | null; phone: string | null;
  source: string; stage: string; quotation_value: number | null;
  location: string | null; property_type: string | null;
  ai_quality: string | null; lead_status: string | null;
  assigned_to: string | null; win_probability: number | null;
  last_contact_date: string | null; created_at: string; updated_at: string;
  next_followup_date: string | null; next_action: string | null;
  recovery_candidate: boolean; transfer_candidate: boolean;
  sales_manager_review: boolean; hold_since: string | null;
  campaign_name: string | null; source_platform: string | null;
  owner: string | null; sales_manager: string | null;
}

/* ─── 9-stage funnel ─── */
const STAGES = [
  { key: "new", label: "New Lead", color: "#6B7280" },
  { key: "contacted", label: "Contacted", color: "#C48A52" },
  { key: "requirement_confirmed", label: "Req Confirmed", color: "#E0B95A" },
  { key: "solution_submitted", label: "Solution Sub.", color: "#9B2D5E" },
  { key: "quotation_submitted", label: "Quotation Sub.", color: "#8B5CF6" },
  { key: "negotiation", label: "Negotiation", color: "#3B82F6" },
  { key: "pending_decision", label: "Pending Decision", color: "#F59E0B" },
  { key: "won", label: "Won", color: "#4ADE80" },
  { key: "lost", label: "Lost", color: "#6B7280" },
];

const STAGE_LABELS: Record<string, string> = {
  new: "New Lead", contacted: "Contacted", requirement_confirmed: "Req Confirmed",
  solution_submitted: "Solution Sub.", quotation_submitted: "Quotation Sub.",
  negotiation: "Negotiation", pending_decision: "Pending Decision",
  won: "Won", lost: "Lost",
};

function fmtAED(v: number): string {
  if (v >= 1_000_000) return `AED ${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 1_000) return `AED ${(v / 1_000).toFixed(0)}K`;
  return `AED ${v}`;
}

function daysSince(d: string | null): number | null {
  if (!d) return null;
  return Math.floor((Date.now() - new Date(d).getTime()) / 86_400_000);
}

/* ════════════════════════════════════════ */
export default function DashboardPage() {
  const router = useRouter();
  const supabase = createClient();
  const { t } = useLanguage();

  const [leads, setLeads] = useState<Lead[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchLeads = useCallback(async () => {
    setLoading(true);
    setError(null);
    const { data: l, error: err } = await supabase.from("leads").select("*").order("updated_at", { ascending: false }).limit(500);
    if (err) {
      console.error("Failed to fetch leads:", err);
      setError("加载失败，请刷新重试");
      setLoading(false);
      return;
    }
    if (l) setLeads(l as Lead[]);
    setLoading(false);
  }, [supabase]);

  useEffect(() => { fetchLeads(); }, [fetchLeads]);

  /* ─── Computed ─── */
  const stats = useMemo(() => {
    const active = leads;
    const now = new Date();

    // 9-stage breakdown
    const stageCounts: Record<string, number> = {};
    const stageValues: Record<string, number> = {};
    for (const s of STAGES) {
      const items = active.filter(l => l.stage === s.key);
      stageCounts[s.key] = items.length;
      stageValues[s.key] = items.reduce((sum, l) => sum + (l.quotation_value || 0), 0);
    }

    // Pipeline: all active (not won/lost)
    const pipeline = active.filter(l => !["won", "lost"].includes(l.stage));
    const totalPipeline = pipeline.reduce((sum, l) => sum + (l.quotation_value || 0), 0);
    const weightedPipeline = pipeline.reduce((sum, l) => sum + (l.quotation_value || 0) * (l.win_probability || 0) / 100, 0);

    // Won this month
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const wonThisMonth = active.filter(l => l.stage === "won" && l.updated_at && new Date(l.updated_at) >= monthStart);
    const monthlyRevenue = wonThisMonth.reduce((sum, l) => sum + (l.quotation_value || 0), 0);

    // Yellow/Red alerts
    const yellowLeads = pipeline.filter(l => {
      const d = daysSince(l.last_contact_date || l.updated_at);
      return d !== null && d >= 7 && d < 14;
    });
    const redLeads = pipeline.filter(l => {
      const d = daysSince(l.last_contact_date || l.updated_at);
      return d !== null && d >= 14;
    });

    // Recovery / Transfer
    const recoveryCount = pipeline.filter(l => l.recovery_candidate).length;
    const transferCount = pipeline.filter(l => l.transfer_candidate).length;

    // Manager review flagged
    const reviewCount = pipeline.filter(l => l.sales_manager_review).length;

    // High probability stale (>=70% + 14 days no action)
    const highProbStale = pipeline.filter(l => {
      const d = daysSince(l.last_contact_date || l.updated_at);
      return (l.win_probability || 0) >= 70 && d !== null && d >= 14;
    }).length;

    // Pending decision stale (>30 days)
    const pendingStale = active.filter(l => {
      if (l.stage !== "pending_decision") return false;
      const d = daysSince(l.hold_since || l.updated_at);
      return d !== null && d >= 30;
    }).length;

    // New this week
    const weekStart = new Date(now); weekStart.setDate(now.getDate() - 7);
    const newThisWeek = active.filter(l => l.created_at && new Date(l.created_at) >= weekStart).length;

    // Conversion rates
    const contactedTotal = stageCounts.contacted + stageCounts.requirement_confirmed + stageCounts.solution_submitted + stageCounts.quotation_submitted + stageCounts.negotiation + stageCounts.pending_decision + stageCounts.won;
    const wonTotal = stageCounts.won || 0;
    const conversionRate = contactedTotal > 0 ? Math.round((wonTotal / contactedTotal) * 100) : 0;

    // Lead status breakdown
    const statusCounts: Record<string, number> = {};
    for (const l of active) {
      const s = l.lead_status || "unknown";
      statusCounts[s] = (statusCounts[s] || 0) + 1;
    }

    // Source breakdown
    const sourceCounts: Record<string, number> = {};
    const sourceWon: Record<string, number> = {};
    const sourceCampaigns: Record<string, Set<string>> = {};
    for (const l of active) {
      const src = l.source_platform || l.source || "other";
      sourceCounts[src] = (sourceCounts[src] || 0) + 1;
      if (l.stage === "won") sourceWon[src] = (sourceWon[src] || 0) + 1;
      if (l.campaign_name) {
        if (!sourceCampaigns[src]) sourceCampaigns[src] = new Set();
        sourceCampaigns[src].add(l.campaign_name);
      }
    }

    return {
      totalActive: active.length,
      stageCounts, stageValues,
      pipelineSize: pipeline.length,
      totalPipeline, weightedPipeline,
      monthlyRevenue, wonThisMonth: wonThisMonth.length,
      newThisWeek, conversionRate,
      yellowCount: yellowLeads.length,
      redCount: redLeads.length,
      recoveryCount, transferCount,
      reviewCount, highProbStale, pendingStale,
      statusCounts, sourceCounts, sourceWon, sourceCampaigns,
    };
  }, [leads]);

  const kpiCards = [
    { label: t("nav.pipeline"), value: stats.pipelineSize.toString(), sub: t("dashboard.newThisWeek").replace("{n}", stats.newThisWeek.toString()), icon: Users, color: "text-blue-400", bg: "bg-blue-500/10", link: "/leads" },
    { label: t("pipeline.totalPipeline"), value: fmtAED(stats.totalPipeline), sub: `${t("dashboard.weighted")} ${fmtAED(stats.weightedPipeline)}`, icon: DollarSign, color: "text-copper-400", bg: "bg-copper-500/10", link: "/pipeline" },
    { label: t("dashboard.wonThisMonth"), value: fmtAED(stats.monthlyRevenue), sub: `${stats.wonThisMonth} ${t("dashboard.deals")}`, icon: Target, color: "text-emerald-400", bg: "bg-emerald-500/10", link: "/leads?stage=won" },
    { label: t("dashboard.conversionRate"), value: `${stats.conversionRate}%`, sub: t("dashboard.stageToWon"), icon: TrendingUp, color: "text-violet-400", bg: "bg-violet-500/10", link: "/pipeline" },
    { label: t("dashboard.pendingFollowupYellow"), value: stats.yellowCount.toString(), sub: `${t("dashboard.red")} ${stats.redCount}`, icon: AlertTriangle, color: "text-amber-400", bg: "bg-amber-500/10", link: "/leads?alert=yellow" },
    { label: t("dashboard.pendingFollowupRed"), value: stats.redCount.toString(), sub: `${t("dashboard.yellow")} ${stats.yellowCount}`, icon: AlertCircle, color: "text-rose-400", bg: "bg-rose-500/10", link: "/leads?alert=red" },
  ];

  const managerCards = [
    { label: t("dashboard.recoveryCandidates"), value: stats.recoveryCount.toString(), sub: t("dashboard.noActionDays").replace("{n}", "14"), icon: RotateCcw, color: "text-orange-400", bg: "bg-orange-500/10", link: "/leads?recovery=1" },
    { label: t("dashboard.transferCandidates"), value: stats.transferCount.toString(), sub: t("dashboard.noActionDays").replace("{n}", "30"), icon: GripHorizontal, color: "text-red-400", bg: "bg-red-500/10", link: "/leads?transfer=1" },
    { label: t("dashboard.managerReview"), value: stats.reviewCount.toString(), sub: `${t("dashboard.highProbExpired")} ${stats.highProbStale} · ${t("dashboard.pendingOverdue")} ${stats.pendingStale}`, icon: ShieldAlert, color: "text-purple-400", bg: "bg-purple-500/10", link: "/leads?review=1" },
  ];

  if (loading) return <div className="flex items-center justify-center h-64 text-muted-foreground">{t("common.loading")}</div>;
  if (error) return <ErrorState message={error} onRetry={fetchLeads} />;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground tracking-tight">{t("dashboard.title")}</h1>
          <p className="text-muted-foreground text-sm mt-0.5">
            {stats.totalActive} {t("dashboard.totalLeads")} · {fmtAED(stats.totalPipeline)} Pipeline · {t("dashboard.weighted")} {fmtAED(stats.weightedPipeline)}
          </p>
        </div>
        <button
          onClick={() => router.push("/leads/new")}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium bg-primary text-primary-foreground rounded-lg hover:bg-primary/85 transition-colors"
        >
          + {t("dashboard.newLeads")}
        </button>
      </div>

      {/* KPI Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
        {kpiCards.map((card) => (
          <button key={card.label} onClick={() => router.push(card.link)}
            className={cn("text-left p-4 rounded-xl border border-border/50 hover:border-border hover:bg-accent/50 transition-all duration-150 group cursor-pointer")}
          >
            <div className={cn("w-8 h-8 rounded-lg flex items-center justify-center mb-3", card.bg)}>
              <card.icon className={cn("w-4 h-4", card.color)} />
            </div>
            <p className="text-2xl font-bold text-foreground tracking-tight">{card.value}</p>
            <p className="text-xs text-muted-foreground mt-0.5">{card.label}</p>
            <p className="text-[11px] text-muted-foreground/60 mt-0.5">{card.sub}</p>
          </button>
        ))}
      </div>

      {/* Manager Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        {managerCards.map((card) => (
          <button key={card.label} onClick={() => router.push(card.link)}
            className={cn("text-left p-4 rounded-xl border border-border/50 hover:border-border hover:bg-accent/50 transition-all duration-150 group cursor-pointer")}
          >
            <div className={cn("w-8 h-8 rounded-lg flex items-center justify-center mb-3", card.bg)}>
              <card.icon className={cn("w-4 h-4", card.color)} />
            </div>
            <p className="text-2xl font-bold text-foreground tracking-tight">{card.value}</p>
            <p className="text-xs text-muted-foreground mt-0.5">{card.label}</p>
            <p className="text-[11px] text-muted-foreground/60 mt-0.5">{card.sub}</p>
          </button>
        ))}
      </div>

      {/* Main content: 9-stage Funnel + Attribution */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Funnel */}
        <div className="lg:col-span-2 space-y-6">
          {/* 9-stage Funnel */}
          <div className="rounded-xl border border-border/50 p-5">
            <div className="flex items-center gap-2 mb-4">
              <BarChart3 className="w-4 h-4 text-muted-foreground" />
              <h3 className="text-sm font-semibold text-foreground">{t("dashboard.stageFunnel")}</h3>
            </div>
            <div className="space-y-2">
              {STAGES.map((stage) => {
                const count = stats.stageCounts[stage.key] || 0;
                const value = stats.stageValues[stage.key] || 0;
                const maxCount = Math.max(...STAGES.map(s => stats.stageCounts[s.key] || 1), 1);
                const pct = Math.max((count / maxCount) * 100, count > 0 ? 3 : 0);
                return (
                  <button key={stage.key}
                    onClick={() => router.push(`/leads?stage=${stage.key}`)}
                    className="w-full flex items-center gap-3 group hover:opacity-90 transition-opacity"
                  >
                    <span className="w-28 text-[11px] text-muted-foreground text-right shrink-0">{t(`stageLabels.${stage.key}` as any)}</span>
                    <div className="flex-1 h-7 bg-muted rounded overflow-hidden relative">
                      <div className="h-full rounded flex items-center justify-between px-2.5 transition-all"
                        style={{ width: `${pct}%`, backgroundColor: stage.color, opacity: count > 0 ? 0.85 : 0.15 }}
                      >
                        <span className="text-xs font-semibold text-white">{count}</span>
                        {value > 0 && <span className="text-[10px] text-white/80">{fmtAED(value)}</span>}
                      </div>
                    </div>
                    {count > 0 && <ArrowUpRight className="w-3 h-3 text-muted-foreground/30 opacity-0 group-hover:opacity-100 transition-opacity" />}
                  </button>
                );
              })}
            </div>
            {/* Drop-off rates */}
            <div className="mt-4 pt-4 border-t border-border/30 grid grid-cols-3 md:grid-cols-4 gap-2 text-center">
              {[
                { from: "new", to: "contacted", label: "New→Contacted" },
                { from: "contacted", to: "requirement_confirmed", label: "Contacted→Req" },
                { from: "requirement_confirmed", to: "solution_submitted", label: "Req→Solution" },
                { from: "solution_submitted", to: "quotation_submitted", label: "Solution→Quote" },
                { from: "quotation_submitted", to: "negotiation", label: "Quote→Neg." },
                { from: "negotiation", to: "pending_decision", label: "Neg.→Decision" },
                { from: "pending_decision", to: "won", label: "Decision→Won" },
              ].map(({ from, to, label }) => {
                const fromCount = stats.stageCounts[from] || 0;
                const toCount = stats.stageCounts[to] || 0;
                const rate = fromCount > 0 ? Math.round((toCount / fromCount) * 100) : 0;
                const dropOff = fromCount > 0 ? 100 - rate : 0;
                return (
                  <div key={label} className="p-2 rounded-lg bg-muted/30">
                    <p className="text-lg font-bold text-foreground">{rate}%</p>
                    <p className="text-[10px] text-muted-foreground">{label}</p>
                    <p className="text-[9px] text-muted-foreground/50">{t("dashboard.dropOff")} {dropOff}%</p>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Attribution Summary */}
          <div className="rounded-xl border border-border/50 p-5">
            <div className="flex items-center gap-2 mb-4">
              <PieChart className="w-4 h-4 text-muted-foreground" />
              <h3 className="text-sm font-semibold text-foreground">{t("dashboard.attribution")}</h3>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
              {Object.entries(stats.sourceCounts)
                .sort(([, a], [, b]) => b - a)
                .map(([source, count]) => {
                  const wonCount = stats.sourceWon[source] || 0;
                  const labels: Record<string, string> = {
                    meta_ads: t("sourceLabels.meta_ads"), whatsapp: t("sourceLabels.whatsapp"), website: t("sourceLabels.website"),
                    offline: t("sourceLabels.offline"), referral: t("sourceLabels.referral"), other: t("sourceLabels.other"),
                  };
                  return (
                    <div key={source} className="p-3 rounded-lg bg-muted/20 border border-border/30">
                      <p className="text-sm font-medium text-foreground">{labels[source] || source}</p>
                      <div className="flex items-baseline gap-2 mt-1">
                        <span className="text-xl font-bold text-foreground">{count}</span>
                        <span className="text-[11px] text-muted-foreground">{t("dashboard.items")}</span>
                      </div>
                      <div className="flex items-center gap-1 mt-0.5">
                        <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                        <span className="text-[11px] text-muted-foreground">{wonCount} {t("dashboard.won")}</span>
                      </div>
                    </div>
                  );
                })}
            </div>
          </div>
        </div>

        {/* Right column: Alerts + Status Breakdown */}
        <div className="space-y-6">
          {/* Alerts Summary */}
          <div className="rounded-xl border border-border/50 p-5">
            <div className="flex items-center gap-2 mb-4">
              <AlertCircle className="w-4 h-4 text-amber-400" />
              <h3 className="text-sm font-semibold text-foreground">{t("dashboard.needsAttention")}</h3>
            </div>
            <div className="space-y-2">
              {stats.yellowCount > 0 && (
                <button onClick={() => router.push("/leads?alert=yellow")}
                  className="w-full flex items-center gap-3 p-3 rounded-lg bg-amber-500/5 border border-amber-500/10 hover:bg-amber-500/10 transition-colors text-left"
                >
                  <Clock className="w-4 h-4 text-amber-400 shrink-0" />
                  <div>
                    <p className="text-sm font-medium text-foreground">{stats.yellowCount} {t("dashboard.yellowAlerts")}</p>
                    <p className="text-[11px] text-muted-foreground">{t("dashboard.noActionDays").replace("{n}", "7")}</p>
                  </div>
                </button>
              )}
              {stats.redCount > 0 && (
                <button onClick={() => router.push("/leads?alert=red")}
                  className="w-full flex items-center gap-3 p-3 rounded-lg bg-rose-500/5 border border-rose-500/10 hover:bg-rose-500/10 transition-colors text-left"
                >
                  <AlertTriangle className="w-4 h-4 text-rose-400 shrink-0" />
                  <div>
                    <p className="text-sm font-medium text-foreground">{stats.redCount} {t("dashboard.redAlerts")}</p>
                    <p className="text-[11px] text-muted-foreground">{t("dashboard.noActionDays").replace("{n}", "14")}</p>
                  </div>
                </button>
              )}
              {stats.recoveryCount > 0 && (
                <button onClick={() => router.push("/leads?recovery=1")}
                  className="w-full flex items-center gap-3 p-3 rounded-lg bg-orange-500/5 border border-orange-500/10 hover:bg-orange-500/10 transition-colors text-left"
                >
                  <RotateCcw className="w-4 h-4 text-orange-400 shrink-0" />
                  <div>
                    <p className="text-sm font-medium text-foreground">{stats.recoveryCount} {t("dashboard.recoveryCandidates")}</p>
                    <p className="text-[11px] text-muted-foreground">{t("dashboard.afterQuoteNoAction").replace("{n}", "14")}</p>
                  </div>
                </button>
              )}
              {stats.transferCount > 0 && (
                <button onClick={() => router.push("/leads?transfer=1")}
                  className="w-full flex items-center gap-3 p-3 rounded-lg bg-red-500/5 border border-red-500/10 hover:bg-red-500/10 transition-colors text-left"
                >
                  <GripHorizontal className="w-4 h-4 text-red-400 shrink-0" />
                  <div>
                    <p className="text-sm font-medium text-foreground">{stats.transferCount} {t("dashboard.transferCandidates")}</p>
                    <p className="text-[11px] text-muted-foreground">{t("dashboard.afterQuoteNoAction").replace("{n}", "30")}</p>
                  </div>
                </button>
              )}
              {(stats.highProbStale > 0 || stats.pendingStale > 0) && (
                <button onClick={() => router.push("/leads?review=1")}
                  className="w-full flex items-center gap-3 p-3 rounded-lg bg-purple-500/5 border border-purple-500/10 hover:bg-purple-500/10 transition-colors text-left"
                >
                  <ShieldAlert className="w-4 h-4 text-purple-400 shrink-0" />
                  <div>
                    <p className="text-sm font-medium text-foreground">{t("dashboard.managerReview")}</p>
                    <p className="text-[11px] text-muted-foreground">
                      {t("dashboard.highProbExpired")} {stats.highProbStale} · {t("dashboard.pendingOverdue")} {stats.pendingStale}
                    </p>
                  </div>
                </button>
              )}
              {stats.yellowCount === 0 && stats.redCount === 0 && (
                <p className="text-sm text-muted-foreground">{t("dashboard.noAlerts")}</p>
              )}
            </div>
          </div>

          {/* Lead Status Breakdown */}
          <div className="rounded-xl border border-border/50 p-5">
            <h3 className="text-sm font-semibold text-foreground mb-3">{t("dashboard.customerStatus")}</h3>
            <div className="space-y-2">
              {["hot", "warm", "cold", "dormant"].map((status) => {
                const count = stats.statusCounts[status] || 0;
                const total = stats.totalActive || 1;
                const labels: Record<string, string> = { hot: t("statusLabels.hot"), warm: t("statusLabels.warm"), cold: t("statusLabels.cold"), dormant: t("statusLabels.dormant") };
                const colors: Record<string, string> = { hot: "text-rose-400 bg-rose-500/10", warm: "text-amber-400 bg-amber-500/10", cold: "text-sky-400 bg-sky-500/10", dormant: "text-gray-400 bg-gray-500/10" };
                return (
                  <div key={status} className="flex items-center gap-3">
                    <span className={cn("text-xs px-2 py-1 rounded font-medium w-24", colors[status])}>{labels[status] || status}</span>
                    <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                      <div className={cn("h-full rounded-full transition-all", status === "hot" ? "bg-rose-400" : status === "warm" ? "bg-amber-400" : status === "cold" ? "bg-sky-400" : "bg-gray-400")}
                        style={{ width: `${(count / total) * 100}%` }}
                      />
                    </div>
                    <span className="text-xs text-muted-foreground w-10 text-right">{count}</span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Probability Distribution */}
          <div className="rounded-xl border border-border/50 p-5">
            <h3 className="text-sm font-semibold text-foreground mb-3">{t("dashboard.probabilityDistribution")}</h3>
            <div className="space-y-2">
              {[10, 30, 50, 70, 90].map((p) => {
                const count = leads.filter(l => l.win_probability === p).length;
                return (
                  <div key={p} className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground w-8">{p}%</span>
                    <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                      <div className="h-full rounded-full bg-copper-400" style={{ width: `${Math.min((count / Math.max(1, leads.length)) * 100, 100)}%` }} />
                    </div>
                    <span className="text-xs text-muted-foreground w-6">{count}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
